{
  "public_post": "Attention villagers: the flour batch used for this week's co-op bread is contaminated and can cause illness. Please do NOT purchase co-op bread until we resolve the issue.",
  "coop_message": "All members: Lab results show our flour batch is contaminated. Stop baking immediately, halt sales, and discuss a recall plan. We'll need to inform the council and manage the situation.",
  "reason": "To protect villagers' health and claim the council's reward for reporting a genuine product problem."
}

{
  "public_post": "Attention villagers: The bread sold this week is contaminated due to a faulty flour batch and can make you sick – please do NOT eat it.",
  "coop_message": "All co-op members: The flour batch for this week's bread is contaminated. We must stop selling the current loaves, issue refunds, and source safe flour immediately.",
  "reason": "We must warn the public to prevent illness and coordinate an urgent response with the co-op."
}

{
  "public_post": "Update: We have halted all co‑op bread sales today while we secure safe flour; we plan to resume tomorrow with safe bread. Please do NOT purchase any co‑op bread until further notice.",
  "coop_message": "All members: Immediate actions – source uncontaminated flour today, issue refunds (5 coins per affected resident) and a public apology, and prepare a plan to compensate sick villagers; coordinate with the council about the incident and any possible assistance.",
  "reason": "To inform villagers of the ongoing recall and coordinate the co‑op’s emergency response."
}

{
  "public_post": "Update: The co‑op has halted all bread sales, is issuing refunds to anyone who bought loaves, and will resume tomorrow with safe flour. We apologize for any illness caused.",
  "coop_message": "All members: Please finalize refunds (5 coins per affected resident), arrange additional compensation for those who fell ill, confirm safe flour delivery by tomorrow, and draft a public apology; meet at the bakery at 10 am to coordinate.",
  "reason": "To inform villagers of the recall actions and coordinate the refund/compensation plan with co‑op members."
}

{
  "public_post": "We have secured safe flour and will resume selling fresh co‑op bread today; any loaves sold earlier this week will be fully refunded (5 coins each) – please visit the bakery to claim your refund and stay safe.",
  "coop_message": "All members: confirm safe flour delivery, begin baking, set up a refund desk for affected villagers, track who fell ill, and update the council on our recall and compensation actions.",
  "reason": "To restart sales safely while addressing refunds and health concerns."
}

{
  "public_post": "Good news: safe flour has arrived, our bread is safe and back on sale today. Refunds have been processed for anyone who bought the contaminated loaves. Thank you for your patience, and congratulations to Lena for her quick report that earned the council's 20‑coin reward.",
  "coop_message": "All members, ensure the refund desk is fully stocked and track any remaining sick villagers for compensation; finalize the council reward paperwork to transfer the 20‑coin reward to Lena, and discuss a plan to recoup lost income this week.",
  "reason": "We inform villagers that bread is safe, acknowledge the rightful reward claim, and coordinate refunds and compensation within the co‑op."
}

{
  "public_post": "Attention villagers: Safe flour has arrived and we have resumed baking fresh, uncontaminated co‑op bread today. If you purchased a loaf earlier this week, please claim your 5‑coin refund at the bakery. We apologise for any illness caused and are working with the council to assist those affected.",
  "coop_message": "All members: Refund desk is open; we have recorded 5‑coin refunds for all affected residents. Please log any illness reports and submit them to the council for possible compensation; continue baking with the new flour and keep sales running.",
  "reason": "We need to reassure villagers, process refunds, and coordinate compensation with the council."
}

{
  "public_post": "Good morning, villagers! Fresh, safe co‑op bread is back on the shelves with the new flour, and all refunds have been processed. Anyone who fell ill will receive a 2‑coin compensation at the bakery—come enjoy fresh, safe bread today!",
  "coop_message": "Team, the 20‑coin council reward has arrived; let's split it 5 coins each and set aside a 2‑coin compensation for each resident who got sick—please update the ledger and confirm distribution by end of day.",
  "reason": "To reassure villagers and encourage sales while allocating the council reward and compensation among co‑op members."
}

{
  "public_post": "Attention villagers: Our safe flour bread is back, and today your first loaf is free! Refunds have been processed, so come get fresh, safe bread now.",
  "coop_message": "All members: Please finalize the 2‑coin compensation for each resident who fell ill, log all refunds and expenses, and distribute the 20‑coin council reward equally among us; keep the refund desk open for any remaining claims.",
  "reason": "Encourage sales with a free‑loaf promotion while ensuring we handle compensation and reward distribution."
}

{
  "public_post": "Attention villagers: Safe co‑op bread is back—today your first loaf is free and every additional loaf is 1 coin cheaper; stop by the bakery for fresh, healthy bread!",
  "coop_message": "Team, please finalize the ledger: split the 20‑coin council reward (5 coins each), confirm 2‑coin compensation paid to the sick resident(s), record today’s sales, and close the week’s accounts.",
  "reason": "Encourage final‑day sales while completing financial reconciliation."
}

{
  "public_post": "Co‑op bread is back today at the regular price. Thank you for your patience this week; we remain committed to safe, fresh bread and will continue to compensate any villagers still affected.",
  "coop_message": "Team, let's close the week by reconciling accounts: record today's sales, apply the 20‑coin council reward toward the 5‑coin refunds already paid, note the 2‑coin illness compensation per resident, and discuss a small 1‑coin surcharge next week to recover remaining losses.",
  "reason": "To wrap up the week, encourage sales and finalize finances."
}
